import{_ as e,o,c as a,a0 as r}from"./chunks/framework.ZC3WYqLu.js";const f=JSON.parse('{"title":"HTTP(s), Protocols","description":"","frontmatter":{},"headers":[],"relativePath":"dev/fundamentals/http-and-protocols/index.md","filePath":"dev/fundamentals/http-and-protocols/README.md"}'),s={name:"dev/fundamentals/http-and-protocols/index.md"};function n(i,t,d,c,l,h){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="http-s-protocols" tabindex="-1">HTTP(s), Protocols <a class="header-anchor" href="#http-s-protocols" aria-label="Permalink to &quot;HTTP(s), Protocols&quot;">​</a></h1><p>It is recommended that CASS repositories serve resources in a secure fashion using SSL certificates.</p><h2 id="default-installation-configuration" tabindex="-1">Default Installation Configuration <a class="header-anchor" href="#default-installation-configuration" aria-label="Permalink to &quot;Default Installation Configuration&quot;">​</a></h2><p>CASS has the following endpoints exposed by default:</p><table tabindex="0"><thead><tr><th><strong>Port</strong></th><th><strong>Service</strong></th><th><strong>Notes</strong></th></tr></thead><tbody><tr><td>80</td><td>Apache2/HTTPD/...</td><td>Uses proxy_http to send requests to PM2 @port 8080</td></tr><tr><td>8080</td><td>PM2/Node</td><td>Runs the CaSS Repo</td></tr><tr><td>9200</td><td>ElasticSearch</td><td>Only responds to localhost</td></tr></tbody></table><h2 id="https" tabindex="-1">HTTPS <a class="header-anchor" href="#https" aria-label="Permalink to &quot;HTTPS&quot;">​</a></h2><p>The default installation method of CASS is compatible with <a href="https://letsencrypt.org/" target="_blank" rel="noreferrer">LetsEncrypt</a>, a project to provide SSL certificates to anyone. <em>It is recommended to create a cron job to renew your LetsEncrypt certificate.</em></p><p>Other certificate providers are also supported. Configuration of the server should be done according to the certificate provider instructions.</p><div class="tip custom-block"><p class="custom-block-title">NOTE</p><p>Use the <code>--apache</code> option to ensure the configuration of apache instead of other HTTP servers</p></div><h2 id="websockets" tabindex="-1">WebSockets <a class="header-anchor" href="#websockets" aria-label="Permalink to &quot;WebSockets&quot;">​</a></h2><p>CASS allows for websocket connections. When connected, CASS will echo the identifier for any object that has been updated to all connected websockets.</p><p>This allows for</p><ul><li>Smarter applications that can update themselves when new data has been saved to the repository</li><li>Software that monitors CASS and performs some operation when data is updated, such as search aggregators</li></ul>',13)])])}const u=e(s,[["render",n]]);export{f as __pageData,u as default};
